      checks.forEach(function(x){if(x.status!=='blocked'||(d.checks||[]).indexOf(x.id)<0)return;if((d.badChecks||[]).indexOf(x.id)>=0)bad=true;var g=releaseGuidance(x.id);reasons.push({severity:'warning',title:x.label||x.id,detail:x.detail||'',owner:g[0],action:g[1]});});
      alerts.forEach(function(a){var id=String(a&&a.id||'');if(!id)return;var mine=d.monitor?d.monitor(id):d.catchAll&&!claimedAlert(id);if(!mine)return;if(d.backup&&!backupCurrent&&(id==='backup_missing'||id==='backup_stale'))return;var g=monitorGuidance(a);reasons.push({severity:a.severity==='critical'?'critical':'warning',title:a.title||id,detail:a.detail||'',owner:g.owner,action:g.action,diagnostics:id==='client_errors'||id.indexOf('performance_')===0,backupNow:id.indexOf('backup_')===0&&id!=='backup_download_budget'});});
      if(d.backup&&!backupCurrent)reasons.push({severity:'warning',title:backup&&backup.takenAt?'Database backup is '+age(backup.takenAt).replace(' ago','')+' old':'No verified database backup',detail:'The automatic daily backup should be less than 36 hours old.',owner:'System administrator',action:'Create a verified backup now, then investigate why the daily schedule was missed.',backupNow:true});
      if(d.monitorHealth){var ranAt=Number(monitor&&monitor.evaluatedAt||0);if(!ranAt||now-ranAt>MONITOR_STALE_MS)reasons.push({severity:'warning',title:ranAt?'Hourly production monitor last reported '+age(ranAt):'Hourly production monitor has not reported yet',detail:'It should report every hour. Without it, backup, speed, and error warnings stop updating.',owner:'System administrator',action:'In Firebase, confirm the evaluateProductionHealth scheduled Function is deployed and check its logs for failures.'});}
