  bindHistoricalMaintenance=function(){var statusEl=document.getElementById('opsHistoricalStatus'),button=document.getElementById('opsHistoricalPrepare');if(!statusEl||!button)return;historicalStatus().then(function(status){statusEl.innerHTML=historyStateText(status);button.textContent=v8ReportingReady(status)?'Recheck historical reporting':'Prepare all historical reporting';button.onclick=function(){if(!confirm('Prepare Home, Sales History, and Sales Analytics in one continuous run now? The owner-approved Firestore-only summary stage is capped at 50,000 reads, is audited, and never changes sales, stock, settlements, journals, or Finance Books.'))return;button.disabled=true;button.textContent='Preparing all reports…';var latest=status;runHistoricalStage('sales-replica-backfill',replicaStageState(latest),'Historical sales replica',statusEl).then(historicalStatus).then(function(next){latest=next;return runHistoricalStage('sales-at-backfill',salesAtStageState(latest),'Sales date index',statusEl);}).then(historicalStatus).then(function(next){latest=next;return runHistoricalStage('sales-ledger-backfill',dependentStageState(latest,'salesLedger',2),'Sales ledger summaries',statusEl);}).then(historicalStatus).then(function(next){latest=next;return runHistoricalStage('sales-rollup-backfill',v8RollupState(latest),'Home, Sales History, and Analytics summaries',statusEl,{completionOverride:true});}).then(historicalStatus).then(function(done){status=done;statusEl.innerHTML=historyStateText(done);if(!v8ReportingReady(done))throw new Error('Historical reporting did not pass its V8 completion check. Progress was saved safely.');alert('Historical reporting is ready for Home, Sales History, and Sales Analytics.');}).catch(function(error){return historicalStatus().then(function(fresh){status=fresh;statusEl.innerHTML=historyStateText(fresh)+'<br>Progress saved safely: '+esc(error&&error.message||error);});}).finally(function(){button.disabled=false;button.textContent=v8ReportingReady(status)?'Recheck historical reporting':'Resume all historical reporting';});};}).catch(function(error){statusEl.textContent='Status unavailable: '+String(error&&error.message||error);button.disabled=true;});};
  function render(rows){
    var root=document.getElementById('operationsRoot');if(!root)return;
    var agg=aggregate(rows.map(function(x){return x.row;})),latest=agg.latest?new Date(agg.latest).toLocaleString():'No telemetry received';
    root.innerHTML=posCapacityPanel()+exceptionPanel()+safeToOperatePanel()+releaseReadyPanel()+'<details id="operationsSystemHealth" style="margin-top:1.2rem;scroll-margin-top:1rem;"><summary style="cursor:pointer;font-weight:700;color:var(--bd);">Technical diagnostics — application performance by build</summary><div style="display:flex;justify-content:space-between;gap:1rem;align-items:end;flex-wrap:wrap;margin:1rem 0;"><p style="font-size:.8rem;color:var(--tl);margin:0;">For the system administrator when investigating slowness or errors. These are not daily business tasks.</p><label style="font-size:.75rem;color:var(--tl);">Period <select id="opsHealthDays" style="margin-left:.35rem;padding:.4rem;border:1px solid var(--cd);border-radius:6px;"><option value="7"'+(days===7?' selected':'')+'>Last 7 days</option><option value="30"'+(days===30?' selected':'')+'>Last 30 days</option></select></label></div><div style="padding:.8rem;margin-bottom:.75rem;border:1px solid var(--cd);background:#f7f7f4;border-radius:8px;font-size:.75rem;line-height:1.5;"><b>How to read these figures:</b> Average is the usual recorded time. Worst is the slowest recorded result. Samples are the number of times the system measured an activity. Failed means an activity did not complete normally. Client errors are privacy-safe error counts, not customer or payment details. <b>GOOD</b> is within target, <b>WATCH</b> is close to the limit, <b>ACTION</b> needs investigation, and <b>NO DATA</b> means the activity was not measured in the selected period.</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(205px,1fr));gap:.75rem;">'+METRICS.map(function(d){return card(d,agg.metrics[d.key]||{});}).join('')+'</div><div style="display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:.75rem;margin-top:.75rem;"><div style="padding:.8rem;border-radius:8px;background:var(--cr);border:1px solid var(--cd);"><b>'+agg.samples+'</b><br><span style="font-size:.72rem;color:var(--tl);">total measurements recorded</span></div><div style="padding:.8rem;border-radius:8px;background:'+(agg.errors?'#fde8e8':'var(--cr)')+';border:1px solid var(--cd);"><b>'+agg.errors+'</b><br><span style="font-size:.72rem;color:var(--tl);">privacy-safe client errors</span></div><div style="padding:.8rem;border-radius:8px;background:var(--cr);border:1px solid var(--cd);"><b>'+esc(latest)+'</b><br><span style="font-size:.72rem;color:var(--tl);">most recent measurement received</span></div></div><div style="margin-top:1rem;background:var(--cr);border:1px solid var(--cd);border-radius:10px;padding:1rem;overflow-x:auto;"><h4 style="font-family:\'Playfair Display\',serif;color:var(--bd);margin:0 0 .65rem;">Performance history</h4><table style="width:100%;border-collapse:collapse;font-size:.78rem;"><thead><tr style="text-align:left;border-bottom:2px solid var(--cd);"><th style="padding:.5rem;">Day</th><th style="padding:.5rem;text-align:right;">Measurements</th><th style="padding:.5rem;text-align:right;">Slow or failed checks</th><th style="padding:.5rem;text-align:right;">Errors</th><th style="padding:.5rem;">Application builds measured</th></tr></thead><tbody>'+renderRows(rows)+'</tbody></table></div><p style="font-size:.72rem;color:var(--tl);margin-top:.75rem;">System administrator: investigate ACTION metrics or new client errors before publishing. These are averages and worst observations, not percentile measurements.</p></details>';
    document.getElementById('opsHealthDays').onchange=function(){days=Number(this.value)===30?30:7;load();};
    var authz=global.__accazaAuthz;if(authz&&authz.role==='superadmin'){root.insertAdjacentHTML('beforeend',historicalMaintenancePanel()+'<section style="margin-top:1.2rem;padding:.9rem;border:1px solid #efb5b5;background:#fff5f5;border-radius:9px;"><div style="font-weight:700;color:#8b1e1e;">Emergency: sign out every device</div><div style="font-size:.8rem;color:#5c4033;margin:.35rem 0 .6rem;">Use only when downloads spike from tabs you cannot reach, or a device is lost. Every Admin, POS and Finance Books session signs out, including yours. Staff must sign in again; unsynced POS sales stay queued on each device and sync after sign-in. A cashier ringing up a sale gets up to 90 seconds to finish or clear it first, then that device signs out too. Customers are not affected.</div><button id="opsSignOutAll" style="border:1px solid #8b1e1e;background:#8b1e1e;color:#fff;border-radius:6px;padding:.45rem .8rem;cursor:pointer;">Sign out every device</button></section>');bindHistoricalMaintenance();var signOutAll=document.getElementById('opsSignOutAll');if(signOutAll)signOutAll.onclick=function(){var a=global.__accaza,dialog=global.AccazaFormDialog;if(!a||!a.callables||!a.callables.signOutAllPortalSessions||!dialog){alert('Refresh Admin first; the sign-out service is not loaded.');return;}dialog.run({title:'Sign out every device',subtitle:'Every Admin, POS and Finance Books session signs out, including this one. A cashier mid-sale has up to 90 seconds to finish or clear it first. Recorded in the audit log.',submitLabel:'Sign out every device',busyLabel:'Signing out…',fields:[{name:'reason',label:'Reason',type:'textarea',required:true,value:'',validate:function(v){return String(v||'').length<5?'Enter a reason of at least 5 characters.':'';}},{name:'confirmed',label:'I understand every staff member must sign in again',type:'checkbox',required:true,value:false}]},function(v){var reason=String(v.reason||'').trim();if(reason.length<5)throw new Error('Enter a reason of at least 5 characters.');if(v.confirmed!==true)throw new Error('Tick the confirmation to continue.');return a.callables.signOutAllPortalSessions({reason:reason});}).then(function(r){if(!r)return;var d=r&&r.data||r||{};alert('Done: '+(d.revoked||0)+' of '+(d.accounts||0)+' accounts signed out'+(d.failed?(', '+d.failed+' failed'):'')+'. Open tabs sign out now (a cashier mid-sale finishes first, within 90 seconds); very old tabs within an hour.');}).catch(function(e){if(e&&e.code==='cancelled')return;alert('Sign-out failed: '+((e&&e.message)||e));});};}
    var refresh=document.getElementById('opsRefreshExceptions');if(refresh)refresh.onclick=function(){if(loading)return;exceptionData=null;refresh.disabled=true;refresh.textContent='Checking…';load(true);};
    var release=document.getElementById('opsRefreshRelease');if(release)release.onclick=function(){certificationData=null;validationData=null;load();};
    root.querySelectorAll('#opsBackupNow,[data-ops-backup-now]').forEach(function(backupNow){backupNow.onclick=function(){if(!confirm('Create a new encrypted-access database backup in the protected project bucket now? This reads current business data but does not change sales, stock, or Finance Books.'))return;backupNow.disabled=true;backupNow.textContent='Creating backup…';global.__accaza.runDatabaseBackupNow().then(function(result){backupData=result&&result.data||result;certificationData=null;validationData=null;load();}).catch(function(error){alert('Could not create the backup: '+String(error&&error.message||error));backupNow.disabled=false;backupNow.textContent='Create verified backup now';});};});
    root.querySelectorAll('[data-ops-tab]').forEach(function(button){button.onclick=function(){route(this.getAttribute('data-ops-tab'));};});
    root.querySelectorAll('[data-resolve-background]').forEach(function(button){button.onclick=function(){var id=this.getAttribute('data-resolve-background');if(!id||!global.AccazaFormDialog)return;global.AccazaFormDialog.run({title:'Mark background failure resolved',subtitle:'Saved to the audit log with your name. An order that is still incomplete cannot be closed here: complete it first, and the card closes on the next health check.',submitLabel:'Mark resolved',busyLabel:'Checking…',fields:[{name:'note',label:'What you checked and how it was completed',type:'textarea',rows:3,required:true,maxLength:500,placeholder:'Example: Ran Check past sales; order POS-DZQN35 now shows its inventory posting.'}]},function(values){if(String(values.note||'').length<10)throw new Error('Write at least 10 characters on what was checked and fixed.');return global.__accaza.resolveBackgroundFailure(id,values.note);}).then(function(){exceptionData=null;load();}).catch(function(){});};});
    root.querySelectorAll('[data-repair-inventory-marker]').forEach(function(button){button.onclick=function(){var orderId=this.getAttribute('data-repair-inventory-marker');if(!orderId||!confirm('Complete the inventory posting for '+orderId+'? Future orders use their immutable sale-time plan. Older orders retain their recorded movements without guessing from today’s recipe.'))return;button.disabled=true;button.textContent='Verifying…';global.__accaza.repairOrderInventoryMarker(orderId).then(function(result){var data=result&&result.data||result;alert(data&&data.duplicate?'Inventory posting is already complete.':data&&data.legacyEvidenceSealed?'Historical inventory evidence sealed. No stock was changed and today’s recipe was not used.':'Inventory posting completed. '+Number(data&&data.completed||0)+' missing sale-time movement(s) were posted once; COGS remains linked.');exceptionData=null;load();}).catch(function(error){alert('Could not complete inventory posting: '+String(error&&error.message||error));button.disabled=false;button.textContent='Complete inventory posting';});};});
  }
  function load(forceExceptions){
    if(loading)return;loading=true;var root=document.getElementById('operationsRoot');if(root)root.innerHTML=posCapacityPanel()+'<p style="padding:2rem;text-align:center;color:var(--tl);">Loading bounded operational data…</p>';
    var a=global.__accaza;if(!a){loading=false;if(root)root.innerHTML=posCapacityPanel()+'<div style="padding:1rem;border:1px solid #ead39a;background:#fffaf0;color:#7a5200;border-radius:8px;">System data connection is unavailable. POS capacity remains available because it uses the local build artifact.</div>';return;}
    var keys=Array.from({length:days},function(_,i){return dateKey(i);});
    var health=Promise.all(keys.map(function(day){return a.get(a.ref(a.db,'clientTelemetryDaily/'+day)).then(function(s){return{day:day,row:s.val()||null};});}));
    var cached=forceExceptions?null:(exceptionData||sharedExceptionData());
    var exceptions=cached?Promise.resolve(cached):getOperationalExceptions(Boolean(forceExceptions));
    var backup=a.get(a.ref(a.db,'systemHealth/backups/latest')).then(function(s){return s.val()||null;});
    var monitor=a.get(a.ref(a.db,'systemHealth/productionMonitor/current')).then(function(s){return s.val()||null;});
    var certification=certificationData?Promise.resolve(certificationData):a.getProductionCertification().then(function(result){return result&&result.data||result;}).catch(function(){return null;});
    var validation=validationData?Promise.resolve(validationData):a.getProductionValidation().then(function(result){return result&&result.data||result;}).catch(function(){return null;});
    Promise.all([health,exceptions,backup,monitor,certification,validation]).then(function(result){serviceRetry=0;if(retryTimer){clearTimeout(retryTimer);retryTimer=null;}exceptionData=result[1];backupData=result[2];productionHealth=result[3];certificationData=result[4];validationData=result[5];render(result[0]);}).catch(function(error){
      var code=String(error&&error.code||'');
      if(code==='functions/internal'||code==='functions/unavailable'||code==='functions/resource-exhausted'){
        var delays=[5000,10000,20000,40000,80000],delay=delays[Math.min(serviceRetry,delays.length-1)];serviceRetry++;
        if(root)root.innerHTML=posCapacityPanel()+'<div style="padding:1rem;border:1px solid #ead39a;background:#fffaf0;color:#7a5200;border-radius:8px;">Operations service is restarting after the billing update. Retrying automatically in '+Math.round(delay/1000)+' seconds… <button id="opsRetryNow" style="margin-left:.5rem;border:1px solid #d2b66d;background:#fff;border-radius:6px;padding:.35rem .6rem;cursor:pointer;">Retry now</button></div>';
        var retryNow=document.getElementById('opsRetryNow');if(retryNow)retryNow.onclick=function(){if(retryTimer)clearTimeout(retryTimer);retryTimer=null;loading=false;load();};
        retryTimer=setTimeout(function(){retryTimer=null;load();},delay);return;
      }
      if(root)root.innerHTML=posCapacityPanel()+'<div style="padding:1rem;border:1px solid #f1b7b7;background:#fff5f5;color:#8b1e1e;border-radius:8px;">Operations Center could not load. '+esc(code||'Check the connection and try again.')+'</div>';
    }).finally(function(){loading=false;});
  }
  global.__accazaRegisterModule('operations',function(tab){if(tab==='operations')load();});
